#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

int main() {
    int n;
    ll k;
    scanf("%d %lld", &n, &k);
    vector<pair<ll, ll>> iv(n);
    for (auto &[a, b] : iv) scanf("%lld %lld", &a, &b);
    sort(iv.begin(), iv.end());
    // Merge intervals that overlap or touch at an endpoint.
    vector<pair<ll, ll>> merged;
    for (auto &[a, b] : iv) {
        if (!merged.empty() && a <= merged.back().second) merged.back().second = max(merged.back().second, b);
        else merged.push_back({a, b});
    }
    // Widest window of blocks l..r whose gap (start of r minus end of l) fits in k.
    int left = 0, best = 1;
    for (int right = 0; right < (int)merged.size(); right++) {
        while (merged[right].first - merged[left].second > k) left++;
        best = max(best, right - left + 1);
    }
    printf("%d\n", (int)merged.size() - best + 1);
}

import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int s = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, s, pos - s);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = nextInt();
        long k = nextLong();
        long[] key = new long[n];
        // Pack (a, b) with a, b < 2^30 to sort by a then b.
        for (int i = 0; i < n; i++) key[i] = nextLong() << 30 | nextLong();
        Arrays.sort(key);
        long mask = (1L << 30) - 1;
        // Merge intervals that overlap or touch at an endpoint.
        long[] ms = new long[n], me = new long[n];
        int m = 0;
        for (long kv : key) {
            long a = kv >>> 30, b = kv & mask;
            if (m > 0 && a <= me[m - 1]) me[m - 1] = Math.max(me[m - 1], b);
            else {
                ms[m] = a;
                me[m++] = b;
            }
        }
        // Widest window of blocks l..r whose gap (start of r minus end of l) fits in k.
        int left = 0, best = 1;
        for (int right = 0; right < m; right++) {
            while (ms[right] - me[left] > k) left++;
            best = Math.max(best, right - left + 1);
        }
        System.out.println(m - best + 1);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
	"slices"
)

var data []byte
var p int

func next() []byte {
	for p < len(data) && data[p] <= ' ' {
		p++
	}
	s := p
	for p < len(data) && data[p] > ' ' {
		p++
	}
	return data[s:p]
}

func nextInt() int64 {
	t := next()
	neg := len(t) > 0 && t[0] == '-'
	if neg {
		t = t[1:]
	}
	var r int64
	for _, c := range t {
		r = r*10 + int64(c-'0')
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := int(nextInt())
	k := nextInt()
	iv := make([][2]int64, n)
	for i := range iv {
		iv[i] = [2]int64{nextInt(), nextInt()}
	}
	slices.SortFunc(iv, func(x, y [2]int64) int {
		if x[0] != y[0] {
			if x[0] < y[0] {
				return -1
			}
			return 1
		}
		if x[1] < y[1] {
			return -1
		}
		if x[1] > y[1] {
			return 1
		}
		return 0
	})
	// Merge intervals that overlap or touch at an endpoint.
	var merged [][2]int64
	for _, p := range iv {
		if len(merged) > 0 && p[0] <= merged[len(merged)-1][1] {
			merged[len(merged)-1][1] = max(merged[len(merged)-1][1], p[1])
		} else {
			merged = append(merged, p)
		}
	}
	// Widest window of blocks l..r whose gap (start of r minus end of l) fits in k.
	left, best := 0, 1
	for right := range merged {
		for merged[right][0]-merged[left][1] > k {
			left++
		}
		best = max(best, right-left+1)
	}
	fmt.Println(len(merged) - best + 1)
}
